css:
/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }

/* The Statventure Editor's shell (Docs/Editor.md, P4): the old game's dark-mode colours with the ember accent,
   Lato 13 px, rows 24 px. The parts' own sheets come after this one and keep to their own classes. */
:root {
  --paper: #1a1c1a;
  --paper-deep: #292c28;
  --line: #3a3d38;
  --ink: #eeeae1;
  --muted: #aaa9a1;
  --soft: #7d817b;
  --ember: #d77a50;
  --ember-pale: #402a23;
  --row: 24px;
}

* { box-sizing: border-box; scrollbar-color: var(--soft) var(--paper-deep); }

/* Nothing is fixed or otherwise in a layer of its own: in the window the page is the main frame, whose root
   scroller is composited, while Chromium's references are captured in an iframe, whose root isn't; a fixed box
   over the root is a layer of its own (grayscale text) in the first and not in the second. */
html, body { height: 100%; }
html { background: var(--paper); }

body { margin: 0; overflow: hidden; color: var(--ink); background: var(--paper); font: 13px/24px Lato; }

button {
  height: var(--row);
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper-deep);
  font: inherit;
  line-height: 22px;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--ember); }
button:active:not(:disabled) { background: var(--ember-pale); }
button:disabled { color: var(--soft); }
button.primary { border-color: var(--ember); color: var(--paper); background: var(--ember); }
button.primary:active:not(:disabled) { background: var(--ember); }

:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }

/* The shell: the top bar, the panes with their splitters, the status line. */
.shell { display: flex; flex-direction: column; height: 100%; }
.topbar { display: flex; flex: none; align-items: center; gap: 4px; height: 33px; padding: 0 8px; border-bottom: 1px solid var(--line); }
.topbar-gap { width: 8px; }
/* Game folder… and About at the right end (M12 step 6, Q30). */
.topbar-fill { flex: 1; }
.panes { display: flex; flex: 1; min-height: 0; }
.pane { flex: 0 1 auto; min-width: 120px; overflow: auto; background: var(--paper-deep); }
.pane[data-pane=form] { flex: 1 1 0; min-width: 200px; }
.splitter { flex: none; width: 4px; cursor: col-resize; user-select: none; }
.splitter:hover, .splitter.dragging { background: var(--ember); }
.shell.resizing, .shell.resizing * { cursor: col-resize; }
.status { flex: none; height: 25px; padding: 0 8px; overflow: hidden; border-top: 1px solid var(--line); color: var(--muted); white-space: nowrap; }

/* Dialogs: a layer over the shell, the box in its middle. */
.dialog-layer { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.5); }
.dialog { width: 420px; max-width: calc(100% - 48px); padding: 12px 16px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.dialog:focus { outline: none; }
.dialog h2 { margin: 0 0 8px; font-size: 15px; font-weight: 700; }
.dialog-content p { margin: 0 0 8px; }
.dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

.credits { max-width: 640px; margin: 0 auto; padding: 24px 28px 32px; color: #eeeae1; font: 13px/20px Lato; }
.credits h1, .credits h2, .credits h3, .credits p { margin: 0; font-weight: 400; }
.credits h1 { font-size: 20px; line-height: 28px; font-weight: 700; }
.credits h2 { margin: 24px 0 10px; padding-bottom: 4px; border-bottom: 1px solid #3a3d38; font-size: 15px; font-weight: 700; }
.credits h3 { font-weight: 700; }
.credits .version, .credits .licence { color: #aaa9a1; }
.credits .notice { white-space: pre-wrap; }
.credits .component { margin-bottom: 12px; }
/* The About dialog (M12 step 6, Q30): the engine's credits (Credits.Css, rules under .credits) in a dialog as wide as
   their column, its content scrolling on its own within the window's height. */
.dialog.about-dialog { display: flex; flex-direction: column; width: 640px; max-height: calc(100% - 48px); }
.about-dialog .dialog-content { flex: 0 1 auto; min-height: 0; overflow: auto; }
.about-dialog .credits { max-width: none; padding: 0 12px 0 0; }
.about-dialog .dialog-buttons { flex: none; }

/* The file browser (Docs/Editor.md, "Opening packs (step 8)", M11-9, P26): a dialog over the shell, wider than the
   others; the places on the left, the folder's listing with its path field on the right. */
.dialog.browser-dialog { width: 760px; --problem: #e5735f; }
.browser { display: flex; gap: 12px; height: 380px; }
.browser-places { display: flex; flex: none; flex-direction: column; width: 150px; overflow: auto; }
.browser-places-title { margin-top: 8px; padding: 0 8px; color: var(--soft); }
.browser button.browser-place { flex: none; overflow: hidden; border-color: transparent; background: transparent; text-align: left; text-overflow: ellipsis; }
.browser button.browser-place.current { background: var(--ember-pale); }
.browser-main { display: flex; flex: 1; flex-direction: column; min-width: 0; }
.browser-bar { display: flex; flex: none; align-items: center; gap: 8px; margin-bottom: 6px; }
.browser-where { flex: 1; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.browser-hidden { display: flex; flex: none; align-items: center; gap: 4px; color: var(--muted); }
.browser-hidden input { margin: 0; accent-color: var(--ember); }
.browser-head, .browser-row { display: flex; gap: 12px; padding: 0 8px; white-space: nowrap; }
.browser-head { flex: none; border-bottom: 1px solid var(--line); color: var(--soft); }
.browser-head .name, .browser-row .name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.browser-head .size, .browser-row .size { flex: none; width: 70px; text-align: right; }
.browser-head .date, .browser-row .date { flex: none; width: 120px; }
.browser-row .size, .browser-row .date { color: var(--muted); }
.browser-listing { flex: 1; min-height: 0; overflow: auto; border: 1px solid var(--line); border-top: none; background: var(--paper); }
.browser-listing:focus { outline: none; }
.browser-listing:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }
.browser-row { height: var(--row); line-height: var(--row); cursor: default; user-select: none; }
.browser-row.selected { background: var(--ember-pale); }
.browser-empty { padding: 0 8px; color: var(--muted); }
.browser-path { flex: none; margin-top: 8px; }
.browser-path input {
  display: block;
  width: 100%;
  height: 24px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.browser-message { flex: none; min-height: 24px; color: var(--problem); }

/* The entry list (Docs/Editor.md, "Opening packs (step 8)", P8): the open pack's name and state, why it is read-only,
   the filter, and the tree of entries by path: folders (a disclosure triangle, as a summary's), then entries with
   their marks and kind's name; the game's entries dimmed (a colour, not opacity: convention 2). Only the rows near
   the pane's view are made, between two spacers (P37); every row is var(--row) high, as EntryList.RowHeight says. */
.entries-part { --problem: #e5735f; padding: 4px 0 12px; }
.entries-head { display: flex; align-items: baseline; gap: 8px; height: 26px; padding: 0 8px; overflow: hidden; white-space: nowrap; }
.entries-pack { flex: 0 1 auto; min-width: 0; overflow: hidden; font-weight: 700; text-overflow: ellipsis; }
.entries-state { flex: none; color: var(--muted); }
.entries-notice { margin: 2px 8px 6px; padding: 4px 8px; border: 1px solid var(--line); border-radius: 3px; color: var(--muted); line-height: 20px; }
.entries-note { overflow-wrap: anywhere; }
.entries-note.unreadable { color: var(--problem); }
.entries-filter {
  display: block;
  width: calc(100% - 16px);
  height: 24px;
  margin: 2px 8px 6px;
  padding: 0 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 22px;
}
.entries-tree { padding: 0 0 4px; }
.entries-tree:focus { outline: none; }
.entries-item { height: var(--row); padding-right: 8px; overflow: hidden; line-height: var(--row); white-space: nowrap; cursor: default; user-select: none; }
.entries-item.entry { display: flex; }
.entries-item.folder { display: list-item; color: var(--muted); list-style: inside disclosure-closed; text-overflow: ellipsis; }
.entries-item.folder.open { list-style-type: disclosure-open; }
.entries-item .name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.entries-item .marks { flex: none; margin-left: 4px; color: var(--ember); font-weight: 700; }
.entries-item .mark + .mark { margin-left: 3px; }
.entries-item .mark.problem, .entries-item .mark.unreadable { color: var(--problem); }
.entries-item .kind { flex: 0 1 auto; min-width: 0; max-width: 55%; margin-left: 8px; overflow: hidden; color: var(--soft); text-overflow: ellipsis; }
.entries-item.game .name { color: var(--muted); }
.entries-item.unreadable .name { color: var(--problem); }
.entries-item.selected { background: var(--ember-pale); }
.entries-tree:focus .entries-item.active { outline: 1px solid var(--ember); outline-offset: -1px; }
.entries-none { padding: 0 12px; color: var(--muted); }

/* The form pane (Docs/Editor.md, "The form (step 9)"): the entry's head, the Form and JSON tabs, a row per field
   (the name, the controls, the unit, tools), groups for records, lists and maps, problems under their rows in red
   (P16); and the entry dialogs' fields. Controls keep the shell's colours (no color-scheme: convention 2). */
.form-part, .dialog { --problem: #e5735f; }

.form-part { padding: 8px 12px 16px; }
.form-part input[type=text], .form-part input[type=number], .form-part select,
.dialog .dialog-field input, .dialog .dialog-field select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.form-part input:disabled, .form-part select:disabled { color: var(--soft); background: var(--paper-deep); }
.form-part input[type=checkbox], .form-part input[type=range] { accent-color: var(--ember); }
.form-part input.bad { border-color: var(--problem); }

/* The entry: its path, kind and actions. */
.form-head { display: flex; align-items: center; gap: 8px; min-height: 28px; margin-bottom: 4px; }
.form-title { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; }
.form-path { font-weight: 700; }
.form-kind, .form-state { margin-left: 10px; color: var(--muted); }
.form-actions { display: flex; flex: none; gap: 4px; }
.form-about { color: var(--muted); }

/* The tabs. */
.form-tabs { display: flex; margin-bottom: 8px; border-bottom: 1px solid var(--line); }
.form-tabs .tab { height: 28px; padding: 0 14px; border: none; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); background: transparent; line-height: 26px; }
.form-tabs .tab.selected { border-bottom-color: var(--ember); color: var(--ink); }
.form-tabs .tab:active:not(:disabled) { background: transparent; }

/* The rows: a leaf's row is a line; a block's is a group (open), its nested rows indented under its summary. A
   narrow pane shrinks the fields rather than wrapping the line. */
.form-rows .row > .line { display: flex; align-items: center; min-height: 26px; }
.form-rows .name { flex: none; width: 140px; padding-right: 8px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.form-rows .controls, .form-rows .inner { display: inline-flex; align-items: center; gap: 4px; min-width: 0; }
.form-rows .controls input, .form-rows .controls select { flex: 0 1 auto; min-width: 48px; }
.form-rows .controls input[type=checkbox] { flex: none; min-width: 0; }
.form-rows .group > summary { min-height: 26px; line-height: 26px; white-space: nowrap; }
.form-rows .group > summary > .name { display: inline-block; width: 127px; vertical-align: top; }
.form-rows .group > summary > .controls, .form-rows .group > summary > .tools { height: 26px; vertical-align: top; }
.form-rows .group .rows, .form-rows .group .items, .form-rows .group .entries { margin-left: 4px; padding-left: 12px; border-left: 1px solid var(--line); }
.form-rows .name.key { display: flex; align-items: center; }
.form-rows .name.key input, .form-rows .name.key select { width: 130px; }
.form-rows .group > summary > .name.key { display: inline-flex; height: 26px; vertical-align: top; }
.form-rows .tools { display: inline-flex; flex: none; align-items: center; gap: 2px; margin-left: 8px; }
.form-rows button.tool { height: 20px; padding: 0 6px; color: var(--muted); line-height: 18px; }
.form-rows button.tool:disabled { color: var(--soft); }
.form-rows .text { width: 260px; }
.form-rows .number { width: 150px; }
.form-rows .component { width: 80px; }
.form-rows .hex { width: 96px; }
.form-rows .slider { width: 140px; margin: 0 4px; }
.form-rows .unit, .form-rows .count, .form-rows .none, .form-rows .summary { color: var(--muted); }
.form-rows .count { margin-right: 4px; }
.form-rows .summary { overflow: hidden; white-space: nowrap; }
.form-rows .swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }

/* Problems (P16): under their row's line, red; the whole entry's at the top. */
.form-part .problem { padding-left: 140px; color: var(--problem); line-height: 20px; }
.form-problems .problem { padding-left: 0; }
.form-rows .has-problem > .line > .name, .form-rows .has-problem > summary > .name { color: var(--problem); }

/* The JSON tab (M11-18, P22). */
.json-bar { display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.json-note { flex: 1; color: var(--muted); }
.json-view.stale .json-note { color: var(--ember); }
.json-text { margin: 0; padding: 6px 8px; overflow-x: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); font: inherit; line-height: 18px; white-space: pre; }
.json-more { margin-top: 6px; color: var(--muted); }

/* The entry dialogs' fields (New, Duplicate, Rename). */
.dialog .dialog-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.dialog .dialog-label { flex: none; width: 110px; color: var(--muted); }
.dialog .dialog-field input, .dialog .dialog-field select { flex: 1; min-width: 0; }
.dialog .dialog-problem { min-height: 24px; color: var(--problem); }

/* "Where is Stat Fick?" (M12 step 6, Q16): a page of its own, its column as wide as the file browser's dialog, the
   browser (Browser.css) built into it in a box of the dialogs' colour, taking the height left. */
.game-screen { --problem: #e5735f; display: flex; justify-content: center; height: 100%; overflow: auto; }
.game-page { display: flex; flex-direction: column; width: 760px; max-width: calc(100% - 32px); height: 100%; min-height: 470px; padding: 24px 0 16px; }
.game-page h1 { flex: none; margin: 0 0 8px; font-size: 20px; font-weight: 700; line-height: 28px; }
.game-page p { flex: none; margin: 0 0 8px; }
.game-version { color: var(--muted); }
.game-problem { color: var(--problem); }
.game-screen .browser { flex: 1; height: auto; min-height: 220px; margin-top: 4px; padding: 12px 16px; border: 1px solid var(--line); border-radius: 4px; background: var(--paper-deep); }
.game-buttons { display: flex; flex: none; justify-content: flex-end; gap: 8px; margin-top: 12px; }

/* Import (Docs/Editor.md, "Import (step 12)"): the import dialog's path field, the replace question, and the
   keep-or-take list of the values that differ when a file is imported again (P29). Controls keep the shell's
   colours (no color-scheme: convention 2). */
.import-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.import-label { flex: none; width: 40px; color: var(--muted); }
.import-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.import-problem { min-height: 24px; color: var(--problem); }  /* the editor's problem red (Form.css gives every dialog it) */

.dialog.import-again-dialog { width: 640px; }
.import-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.import-values { max-height: 290px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.import-row { display: flex; align-items: center; gap: 8px; height: 26px; padding: 0 8px; border-top: 1px solid var(--line); }
.import-row:first-child { border-top: none; }
.import-head { color: var(--muted); }
.import-name { flex: none; width: 200px; overflow: hidden; white-space: nowrap; }
.import-choice { display: flex; flex: 1 1 0; align-items: center; gap: 6px; min-width: 0; overflow: hidden; white-space: nowrap; }
.import-choice input { flex: none; margin: 0; accent-color: var(--ember); }
.import-swatch { flex: none; width: 14px; height: 14px; border: 1px solid var(--line); border-radius: 2px; }
.import-text { overflow: hidden; }

/* The preview pane (Docs/Editor.md, "The preview (step 13)"): the selected entry's preview, its 3D view (a surface,
   left out of the Chromium comparison, P36), its buttons, sliders and stand-ins. Controls keep the shell's colours
   (no color-scheme: convention 2); nothing in a layer of its own. */
.preview-part .preview { padding: 8px 12px 16px; }
.preview-part input[type=text], .preview-part input[type=number], .preview-part select {
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.preview-part select:disabled, .preview-part input:disabled { color: var(--soft); background: var(--paper-deep); }
.preview-part input[type=range], .preview-part input[type=checkbox] { accent-color: var(--ember); }

/* The 3D view, and the empty hosts of a cutscene's element roles over it. */
.preview-stage { position: relative; }
.preview-part .preview-view { display: block; width: 100%; height: 200px; margin-bottom: 8px; border: 1px solid var(--line); background: var(--paper-deep); }
.preview-hosts { position: absolute; top: 1px; left: 1px; right: 1px; height: 200px; overflow: hidden; padding: 4px 6px; pointer-events: none; font-size: 11px; line-height: 14px; }

/* Buttons, lines, sliders. */
.preview-buttons { display: flex; align-items: center; gap: 4px; min-height: 28px; }
.preview-state { margin-left: 8px; color: var(--muted); white-space: nowrap; }
.preview-line { display: flex; align-items: center; gap: 4px; min-height: 26px; }
.preview-name { flex: none; width: 96px; overflow: hidden; color: var(--muted); white-space: nowrap; }
.preview-slider { flex: 1 1 auto; width: 120px; min-width: 60px; margin: 0 4px; }
.preview-timeline { margin-left: 8px; }
.preview-value { flex: none; min-width: 52px; color: var(--muted); white-space: nowrap; }
.preview-number { width: 80px; }
.preview-check { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; white-space: nowrap; }
/* Selects share their line's room from no width of their own (a select's width from its options differs from Chromium's, M5's known difference). */
.preview-part select { flex: 1 1 0; min-width: 0; }

/* Palettes: a swatch and the colour as text per slot. */
.preview-swatch { flex: none; width: 18px; height: 18px; border: 1px solid var(--line); border-radius: 3px; }
.preview-hex { width: 80px; }
.preview-slots { display: flex; flex-wrap: wrap; gap: 4px 10px; }
.preview-slot { display: inline-flex; align-items: center; gap: 4px; }
.preview-slot-name { color: var(--muted); }

/* Stand-ins and the tracks left out. */
.preview-heading { margin-top: 8px; font-weight: 700; }
.preview-about { color: var(--muted); }
.preview-left-out { margin-top: 6px; }
.preview-left-out .preview-about { line-height: 18px; }

/* Why the entry isn't previewed as it is (P35). */
.preview-note { margin-top: 6px; color: var(--ember); line-height: 18px; }

/* References (M11-11; Docs/Editor.md, "How it works", step 10): the reference field's list under a field naming
   another entry (in its row's flow under the row's line, at the field's left and as wide: margin and width set by the
   part), and the referrers in the rename and remove dialogs (P19). Colours from the shell; the problem red from the
   form. */
.form-rows .reference-list {
  box-sizing: border-box;
  max-height: 180px;
  margin: 2px 0 4px;
  padding: 2px 0;
  overflow-x: hidden;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--paper);
  line-height: 22px;
  white-space: nowrap;
}
.form-rows .reference-option { padding: 0 8px; color: var(--ink); }
.form-rows .reference-option.game { color: var(--muted); }
.form-rows .reference-option.active { color: var(--ink); background: var(--line); }
.form-rows .reference-flag { padding: 0 8px; color: var(--problem); }

.dialog .referrers p { margin: 8px 0 4px; }
.dialog .referrer-list { margin: 0 0 8px; padding-left: 18px; color: var(--muted); }
.dialog .referrer-list .more { list-style: none; }
.dialog .referrer-update { display: flex; align-items: center; gap: 6px; }
.dialog .referrer-update input { margin: 0; accent-color: var(--ember); }

/* Saving and mods (Docs/Editor.md, "How it works", step 11): the refusal's list, the Save As dialog's ticks, the New mod
   dialog's fields, and the mod's info in a form of its own (in the form pane). Controls keep the shell's colours (no
   color-scheme: convention 2); the problem red is the one Form.css gives every dialog and the form pane. */
.saving-problems { margin: 0; padding-left: 18px; }
.saving-problems li { margin: 0 0 4px; }
.saving-problem-entry { font-weight: 700; }
.saving-more { color: var(--muted); }

.dialog.saving-save-as { width: 560px; }
.saving-tools { display: flex; gap: 4px; margin: 0 0 8px; }
.saving-entries { max-height: 286px; overflow: auto; border: 1px solid var(--line); border-radius: 3px; background: var(--paper); }
.saving-entry { padding: 2px 8px; border-top: 1px solid var(--line); }
.saving-entry:first-child { border-top: none; }
.saving-line { display: flex; align-items: center; gap: 8px; height: 22px; white-space: nowrap; }
.saving-line input { flex: none; margin: 0; accent-color: var(--ember); }
.saving-path { overflow: hidden; }
.saving-kind { flex: none; color: var(--muted); }
.saving-reason { padding: 0 0 2px 21px; color: var(--problem); }
.saving-entry.not-offered .saving-line { color: var(--soft); }
.saving-entry.not-offered .saving-kind { color: var(--soft); }
.saving-note { min-height: 24px; margin-top: 8px; color: var(--ember); }

.saving-field { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.saving-label { flex: none; width: 40px; color: var(--muted); }
.saving-field input {
  flex: 1;
  min-width: 0;
  height: 22px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: 20px;
}
.saving-problem { min-height: 24px; color: var(--problem); }
.saving-about { color: var(--muted); }

.mod-info-head { display: flex; align-items: center; gap: 10px; min-height: 28px; margin-bottom: 4px; white-space: nowrap; }
.mod-info-title { font-weight: 700; }
.mod-info-path, .mod-info-state { color: var(--muted); }
.mod-info-about { margin: 0 0 12px; color: var(--muted); }
.mod-info-row { display: flex; align-items: flex-start; margin: 0 0 4px; }
.mod-info-label { flex: none; width: 140px; padding-right: 8px; color: var(--muted); line-height: 24px; }
.mod-info-row input { width: 260px; min-width: 48px; }
.mod-info-row textarea {
  width: 360px;
  min-width: 48px;
  height: 106px;
  margin: 0;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  background: var(--paper);
  font: inherit;
  line-height: normal;  /* the engine's textarea lays its lines out at the normal height whatever the author's (Docs/Editor.md, step 11, "Found") */
  resize: none;
}
.mod-info-row textarea:disabled { color: var(--soft); background: var(--paper-deep); }
